<?php $active_menu='employee_leave';include 'header.php';require_once __DIR__.'/../leave.php';oecrm_require_permission($conn,'leave_requests','view');$companyId=oecrm_current_company_id($conn);$flash=$_SESSION['leave_flash']??'';unset($_SESSION['leave_flash']);if(isset($_POST['generate_comp'])){oecrm_require_csrf();oecrm_require_permission($conn,'comp_off','credit');$generated=oecrm_generate_comp_off_credits($conn,$companyId,(int)$_POST['year'],(int)$_POST['month'],(int)$_SESSION['adminId']);$flash=$generated.' comp-off credit(s) generated.';}$requests=mysqli_query($conn,'SELECT r.*,e.name employee_name,e.employeeCode,t.name type_name,(SELECT (b.opening_balance+b.credited+b.adjusted-b.used-b.pending) FROM employee_leave_balances b WHERE b.employee_id=r.employee_id AND b.leave_type_id=r.leave_type_id AND b.balance_year=YEAR(r.start_date)) available_balance FROM leave_requests r JOIN employeestbl e ON e.id=r.employee_id JOIN leavetypetbl t ON t.id=r.leave_type_id WHERE r.company_id='.(int)$companyId.' ORDER BY FIELD(r.status,"pending","approved","rejected"),r.id DESC');$pending=mysqli_fetch_assoc(mysqli_query($conn,'SELECT COUNT(*) c,COALESCE(SUM(payable_days),0) d FROM leave_requests WHERE company_id='.(int)$companyId.' AND status="pending"'));$comp=mysqli_fetch_assoc(mysqli_query($conn,'SELECT COUNT(*) c,COALESCE(SUM(credit_days-debit_days),0) d FROM comp_off_ledger l JOIN employeestbl e ON e.id=l.employee_id WHERE e.company_id='.(int)$companyId.' AND l.status="available" AND (l.expiry_date IS NULL OR l.expiry_date>=CURDATE())'));?>
<div id="page-wrapper" class="compact-admin-page leave-admin-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?><div class="leave-admin-stats"><div><i class="fa fa-clock-o"></i><span><strong><?php echo (int)$pending['c'];?></strong><small>Pending Requests</small></span></div><div><i class="fa fa-calendar-minus-o"></i><span><strong><?php echo number_format($pending['d'],1);?></strong><small>Pending Leave Days</small></span></div><div><i class="fa fa-refresh"></i><span><strong><?php echo number_format($comp['d'],1);?></strong><small>Available Comp-Off</small></span></div><form method="post"><?php echo oecrm_csrf_field();?><input type="hidden" name="generate_comp" value="1"><input type="hidden" name="year" value="<?php echo date('Y');?>"><input type="hidden" name="month" value="<?php echo date('n');?>"><button class="btn btn-primary"><i class="fa fa-magic"></i> Generate Comp-Off</button></form></div><div class="panel panel-default"><div class="panel-heading">Leave Approval</div><div class="panel-body table-responsive"><table class="table foundation-table"><thead><tr><th>Employee</th><th>Dates</th><th>Type</th><th>Days</th><th>Sandwich</th><th>Unpaid</th><th>Balance</th><th>Status</th><th>Reason / Action</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($requests)):?><tr><td><strong><?php echo oecrm_h($r['employee_name']);?></strong><small><?php echo oecrm_h($r['employeeCode']);?></small></td><td><?php echo oecrm_h($r['start_date'].' to '.$r['end_date']);?><small><?php echo oecrm_h($r['subject']);?></small></td><td><?php echo oecrm_h($r['type_name']);?></td><td><?php echo number_format($r['payable_days'],1);?></td><td><?php echo number_format($r['sandwich_days'],1);?></td><td><?php echo number_format($r['unpaid_days'],1);?></td><td><?php echo number_format((float)$r['available_balance'],1);?></td><td><span class="leave-status <?php echo $r['status'];?>"><?php echo ucfirst($r['status']);?></span></td><td><form method="post" action="leaveAction.php" class="leave-approval-actions"><?php echo oecrm_csrf_field();?><input type="hidden" name="request_id" value="<?php echo (int)$r['id'];?>"><input class="form-control" name="note" value="<?php echo oecrm_h($r['approver_note'] ?? '');?>" placeholder="<?php echo $r['status']==='rejected'?'Reject reason / update note':'Remarks';?>"><?php if($r['status']==='pending'):?><button name="action" value="approve" class="btn btn-success btn-sm" title="Approve"><i class="fa fa-check"></i></button><button name="action" value="reject" class="btn btn-danger btn-sm" title="Reject"><i class="fa fa-times"></i></button><?php elseif($r['status']==='rejected'):?><button name="action" value="approve" class="btn btn-success btn-sm" title="Approve rejected request"><i class="fa fa-check"></i></button><button name="action" value="update_note" class="btn btn-primary btn-sm" title="Update reason"><i class="fa fa-save"></i></button><?php else:?><button name="action" value="update_note" class="btn btn-primary btn-sm" title="Update note"><i class="fa fa-save"></i></button><?php endif;?></form></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include 'footer.php';?>
